def build_partial_context_pages():
    """Return fresh complete pages for the fixed first partial graph."""
    pages = {}
    for dva, encoded in _PARTIAL_CONTEXT_PAGES_B85.items():
        page = zlib.decompress(base64.b85decode(encoded))
        if (
            len(page) != PAGE_SIZE
            or hashlib.sha256(page).hexdigest()
            != PARTIAL_CONTEXT_PAGE_SHA256[dva]
        ):
            raise ValueError("G17G partial caller asset changed")
        pages[dva] = page
    return pages
